window.BOOK={"key":"khansa","app":"mutoon-khansa","lsk":"mutoon_khansa_v1","prefix":"kh_","title":"رائية الخنساء","sub":"الشعر العربي · الخنساء (ت نحو ٢٤هـ) · ٣٦ بيتًا","poems":[{"id":"khansa","title":"رائية الخنساء","nazim":"الخنساء تماضر بنت عمرو بن الشريد السلمية","death":"ت نحو ٢٤هـ","meter":"البسيط","source":"ويكي مصدر (نص الديوان في الموسوعة الشعرية): «قذى بعينك أم بالعين عوار»","srcUrl":"https://ar.wikisource.org/wiki/قذى_بعينكِ_أمْ_بالعينِ_عوَّارُ","note":"رائية الخنساء في رثاء أخيها صخر «قذًى بعينكِ أم بالعين عوّار» بنص الديوان (٣٦ بيتًا). لم توجد لها نسخة مشكولة شكلًا تامًّا: النص الرقمي الوحيد الكامل (ويكي مصدر، وهو نص «ديوان الخنساء» بعناية حمدو طمّاس على كتاب أونلاين، ونص موقع الديوان الناقص تسعة أبيات) مشكول نصفه (٤٩٫٨٪)، فأُكمل الشكل يدويًّا: ٦٢٠ حركة مطابقة لما طبعته الشواهد و٥٦١ حركة مكمَّلة بما تقتضيه اللغة والوزن. قوبل اللفظ كلمةً كلمةً بسكربت بما أورده منها «معاهد التنصيص» و«التعازي» و«الكامل» للمبرد و«زهر الآداب» (٢٠ بيتًا)، وأُبقي لفظ الديوان، وفُحص وزن كل شطر، ومواضع التأكد في تقرير المصادر.","verses":[["قَذًى بِعَيْنِكِ أَمْ بِالْعَيْنِ عُوَّارُ","أَمْ ذَرَّفَتْ إِذْ خَلَتْ مِنْ أَهْلِهَا الدَّارُ"],["كَأَنَّ عَيْنِي لِذِكْرَاهُ إِذَا خَطَرَتْ","فَيْضٌ يَسِيلُ عَلَى الْخَدَّيْنِ مِدْرَارُ"],["تَبْكِي لِصَخْرٍ هِيَ الْعَبْرَى وَقَدْ وَلَهَتْ","وَدُونَهُ مِنْ جَدِيدِ التُّرْبِ أَسْتَارُ"],["تَبْكِي خُنَاسٌ فَمَا تَنْفَكُّ مَا عَمَرَتْ","لَهَا عَلَيْهِ رَنِينٌ وَهْيَ مِفْتَارُ"],["تَبْكِي خُنَاسٌ عَلَى صَخْرٍ وَحُقَّ لَهَا","إِذْ رَابَهَا الدَّهْرُ إِنَّ الدَّهْرَ ضَرَّارُ"],["لَا بُدَّ مِنْ مِيتَةٍ فِي صَرْفِهَا عِبَرٌ","وَالدَّهْرُ فِي صَرْفِهِ حَوْلٌ وَأَطْوَارُ"],["قَدْ كَانَ فِيكُمْ أَبُو عَمْرٍو يَسُودُكُمُ","نِعْمَ الْمُعَمَّمُ لِلدَّاعِينَ نَصَّارُ"],["صُلْبُ النَّحِيزَةِ وَهَّابٌ إِذَا مَنَعُوا","وَفِي الْحُرُوبِ جَرِيءُ الصَّدْرِ مِهْصَارُ"],["يَا صَخْرُ وَرَّادَ مَاءٍ قَدْ تَنَاذَرَهُ","أَهْلُ الْمَوَارِدِ مَا فِي وِرْدِهِ عَارُ"],["مَشَى السَّبَنْتَى إِلَى هَيْجَاءَ مُعْضِلَةٍ","لَهُ سِلَاحَانِ أَنْيَابٌ وَأَظْفَارُ"],["وَمَا عَجُولٌ عَلَى بَوٍّ تُطِيفُ بِهِ","لَهَا حَنِينَانِ إِعْلَانٌ وَإِسْرَارُ"],["تَرْتَعُ مَا رَتَعَتْ حَتَّى إِذَا ادَّكَرَتْ","فَإِنَّمَا هِيَ إِقْبَالٌ وَإِدْبَارُ"],["لَا تَسْمَنُ الدَّهْرَ فِي أَرْضٍ وَإِنْ رَتَعَتْ","فَإِنَّمَا هِيَ تَحْنَانٌ وَتَسْجَارُ"],["يَوْمًا بِأَوْجَدَ مِنِّي يَوْمَ فَارَقَنِي","صَخْرٌ وَلِلدَّهْرِ إِحْلَاءٌ وَإِمْرَارُ"],["وَإِنَّ صَخْرًا لَوَالِينَا وَسَيِّدُنَا","وَإِنَّ صَخْرًا إِذَا نَشْتُو لَنَحَّارُ"],["وَإِنَّ صَخْرًا لَمِقْدَامٌ إِذَا رَكِبُوا","وَإِنَّ صَخْرًا إِذَا جَاعُوا لَعَقَّارُ"],["وَإِنَّ صَخْرًا لَتَأْتَمُّ الْهُدَاةُ بِهِ","كَأَنَّهُ عَلَمٌ فِي رَأْسِهِ نَارُ"],["جَلْدٌ جَمِيلُ الْمُحَيَّا كَامِلٌ وَرِعٌ","وَلِلْحُرُوبِ غَدَاةَ الرَّوْعِ مِسْعَارُ"],["حَمَّالُ أَلْوِيَةٍ هَبَّاطُ أَوْدِيَةٍ","شَهَّادُ أَنْدِيَةٍ لِلْجَيْشِ جَرَّارُ"],["نَحَّارُ رَاغِيَةٍ مِلْجَاءُ طَاغِيَةٍ","فَكَّاكُ عَانِيَةٍ لِلْعَظْمِ جَبَّارُ"],["فَقُلْتُ لَمَّا رَأَيْتُ الدَّهْرَ لَيْسَ لَهُ","مُعَاتِبٌ وَحْدَهُ يُسْدِي وَنَيَّارُ"],["لَقَدْ نَعَى ابْنُ نَهِيكٍ لِي أَخَا ثِقَةٍ","كَانَتْ تُرَجَّمُ عَنْهُ قَبْلُ أَخْبَارُ"],["فَبِتُّ سَاهِرَةً لِلنَّجْمِ أَرْقُبُهُ","حَتَّى أَتَى دُونَ غَوْرِ النَّجْمِ أَسْتَارُ"],["لَمْ تَرَهُ جَارَةٌ يَمْشِي بِسَاحَتِهَا","لِرِيبَةٍ حِينَ يُخْلِي بَيْتَهُ الْجَارُ"],["وَلَا تَرَاهُ وَمَا فِي الْبَيْتِ يَأْكُلُهُ","لَكِنَّهُ بَارِزٌ بِالصَّحْنِ مِهْمَارُ"],["وَمُطْعِمُ الْقَوْمِ شَحْمًا عِنْدَ مَسْغَبِهِمْ","وَفِي الْجُدُوبِ كَرِيمُ الْجَدِّ مِيسَارُ"],["قَدْ كَانَ خَالِصَتِي مِنْ كُلِّ ذِي نَسَبٍ","فَقَدْ أُصِيبَ فَمَا لِلْعَيْشِ أَوْطَارُ"],["مِثْلَ الرُّدَيْنِيِّ لَمْ تَنْفَدْ شَبِيبَتُهُ","كَأَنَّهُ تَحْتَ طَيِّ الْبُرْدِ أُسْوَارُ"],["جَهْمُ الْمُحَيَّا تُضِيءُ اللَّيْلَ صُورَتُهُ","آبَاؤُهُ مِنْ طِوَالِ السَّمْكِ أَحْرَارُ"],["مُوَرَّثُ الْمَجْدِ مَيْمُونٌ نَقِيبَتُهُ","ضَخْمُ الدَّسِيعَةِ فِي الْعَزَّاءِ مِغْوَارُ"],["فَرْعٌ لِفَرْعٍ كَرِيمٍ غَيْرِ مُؤْتَشَبٍ","جَلْدُ الْمَرِيرَةِ عِنْدَ الْجَمْعِ فَخَّارُ"],["فِي جَوْفِ لَحْدٍ مُقِيمٌ قَدْ تَضَمَّنَهُ","فِي رَمْسِهِ مُقْمَطِرَّاتٌ وَأَحْجَارُ"],["طَلْقُ الْيَدَيْنِ لِفِعْلِ الْخَيْرِ ذُو فَجَرٍ","ضَخْمُ الدَّسِيعَةِ بِالْخَيْرَاتِ أَمَّارُ"],["لِيَبْكِهِ مُقْتِرٌ أَفْنَى حَرِيبَتَهُ","دَهْرٌ وَحَالَفَهُ بُؤْسٌ وَإِقْتَارُ"],["وَرُفْقَةٌ حَارَ حَادِيهِمْ بِمَهْلَكَةٍ","كَأَنَّ ظُلْمَتَهَا فِي الطِّخْيَةِ الْقَارُ"],["لَا يَمْنَعُ الْقَوْمَ إِنْ سَالُوهُ خُلْعَتَهُ","وَلَا يُجَاوِزُهُ بِاللَّيْلِ مُرَّارُ"]],"secs":{"1":"رائية الخنساء"}}],"sharh":false};
